    border-bottom: 1px solid #e0e0e0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-thread-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: #666;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-thread-btn:hover {
    background: #eee;
}

.thread-root-message {
    padding: 12px 16px;
    background: #f0f4f8;
    border-left: 3px solid #4a9eff;
    margin: 12px 16px;
    border-radius: 4px;
}

.thread-divider {
    border: none;
    border-top: 1px solid #e0e0e0;
    margin: 0 16px;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    padding: 8px;
    margin-bottom: 4px;
}

.thread-input-area {
    padding: 12px 16px;
}
"}

